  ('source_cfpb_auto_compare', 'db_finance_ledger', '{"title": "CFPB auto-loan cost comparison", "source_url": "https://www.consumerfinance.gov/ask-cfpb/what-things-can-i-negotiate-when-shopping-for-a-car-or-auto-loan-en-2132/", "summary": "Official guidance explains that interest rate, term, fees, and optional add-ons affect monthly and total loan cost.", "status": "reviewed", "reviewed_at": "2026-06-15"}', '2026-06-10T08:00:00Z', '2026-06-15T08:30:00Z', 0),
  ('source_cfpb_auto_worksheet', 'db_finance_ledger', '{"title": "CFPB auto-loan worksheet", "source_url": "https://files.consumerfinance.gov/f/documents/201606_cfpb_auto-loan-worksheet.pdf", "summary": "The worksheet separates vehicle price, down payment, trade-in, amount financed, APR, term, optional products, and total cost.", "status": "reviewed", "reviewed_at": "2026-06-15"}', '2026-06-11T08:00:00Z', '2026-06-15T08:30:00Z', 0),
  ('source_cfpb_card_minimum', 'db_finance_ledger', '{"title": "CFPB minimum-payment guidance", "source_url": "https://www.consumerfinance.gov/ask-cfpb/a-box-on-my-credit-card-bill-says-that-i-will-pay-off-the-balance-in-three-years-if-i-pay-a-certain-amount-what-does-that-mean-do-i-have-to-pay-that-much-if-i-pay-that-much-and-make-new-purchases-will-i-still-owe-nothing-after-three-years-en-36/", "summary": "Paying more than the minimum can reduce interest and payoff time; card pressure belongs in the refinance cashflow comparison.", "status": "reviewed", "reviewed_at": "2026-06-15"}', '2026-06-12T08:00:00Z', '2026-06-15T08:30:00Z', 0),
